//! compose-rs's Material 3 components, as Compose's `androidx.compose.material3`:
//! `MaterialTheme` (color scheme, typography, shapes), `Text`, `Surface`, `Button`,
//! `OutlinedButton`, `TextButton`, `Checkbox` and `TextField`, with Compose's parameter names,
//! order and defaults (docs/06-ui.md).

#![forbid(unsafe_code)]
#![allow(non_snake_case)]

// Code generated by `#[composable]` names the runtime `::compose`.
extern crate compose_runtime as compose;

mod components;
mod dialog;
mod icon;
mod list_item;
mod navigation;
mod progress;
mod scaffold;
mod selection;
mod snackbar;
mod theme;

pub use components::{
    AnnotatedText, Button, ButtonColors, ButtonDefaults, Checkbox, CheckboxColors,
    CheckboxDefaults, LOCAL_ABSOLUTE_TONAL_ELEVATION, MINIMUM_INTERACTIVE_SIZE, OutlinedButton,
    Surface, Text, TextButton, TextField, TextFieldColors, TextFieldDefaults,
    minimum_interactive_component_size,
};
pub use dialog::{AlertDialog, DropdownMenu, DropdownMenuItem};
pub use icon::{FloatingActionButton, Icon, IconButton, icons};
pub use list_item::{ListItem, ListItemColors, ListItemDefaults};
pub use navigation::{
    NavigationBar, NavigationBarDefaults, NavigationBarItem, NavigationBarItemColors,
    NavigationBarItemDefaults,
};
pub use progress::{
    CircularProgressIndicator, IndeterminateCircularProgressIndicator,
    IndeterminateLinearProgressIndicator, LinearProgressIndicator, ProgressIndicatorDefaults,
};
pub use scaffold::{
    Card, CardColors, CardDefaults, HorizontalDivider, Scaffold, TopAppBar, TopAppBarColors,
    TopAppBarDefaults, VerticalDivider,
};
pub use selection::{
    RadioButton, RadioButtonColors, RadioButtonDefaults, Slider, SliderColors, SliderDefaults,
    Switch, SwitchColors, SwitchDefaults,
};
pub use snackbar::{
    Snackbar, SnackbarData, SnackbarDuration, SnackbarHost, SnackbarHostState, SnackbarResult,
    SnackbarVisuals,
};
pub use theme::{
    ColorScheme, LOCAL_COLOR_SCHEME, LOCAL_CONTENT_COLOR, LOCAL_SHAPES, LOCAL_TEXT_STYLE,
    LOCAL_TYPOGRAPHY, MaterialTheme, Shapes, Typography, dark_color_scheme, light_color_scheme,
};

// What the defaults of the composables name through `crate::`.
#[doc(hidden)]
pub use compose_foundation::{ScrollState, remember_scroll_state};
pub use compose_ui::{
    AnnotatedString, Color, Dp, FontFamily, FontStyle, IntOffset, Modifier, RECTANGLE_SHAPE, Sp,
    SpanStyle, StrokeCap, TextAlign, TextDecoration, TextOverflow,
};

pub(crate) use selection::blend as selection_blend;

#[doc(hidden)]
pub fn window_default_dialog_properties() -> compose_ui::DialogProperties {
    compose_ui::DialogProperties::default()
}
